import { GetCommandInvocationCommand, SendCommandCommand, SSMClient } from "@aws-sdk/client-ssm";
import { setTimeout as sleep } from "node:timers/promises";

const ssm = new SSMClient({});

/** Start nova-worker as a systemd unit unless it already runs. Safe to call again on a retry. */
export const ensureHarnessRunning = async (vm: Sandbox, task: Task): Promise<void> => {
  const unit = `nova-${task.runId}`;
  const script = `systemctl is-active --quiet ${unit} || ` +
    `systemd-run --uid agent --unit ${unit} /usr/local/bin/nova-worker run /run/nova/task.json`;
  const sent = await ssm.send(new SendCommandCommand({
    InstanceIds: [vm.instanceId],
    DocumentName: "AWS-RunShellScript",
    Parameters: { commands: [script] }, // ends in a second; the unit lives on
  }));
  const commandId = sent.Command?.CommandId ?? "";
  for (;;) {
    await sleep(2_000);
    const inv = await ssm.send(new GetCommandInvocationCommand({ CommandId: commandId, InstanceId: vm.instanceId }))
      .catch(() => undefined); // InvocationDoesNotExist for a moment after sending
    if (inv?.Status === "Success") return;
    if (inv && ["Failed", "Cancelled", "TimedOut"].includes(inv.Status ?? "")) throw new Error(`could not start ${unit}`);
  }
};
